# BASIC Runtime: DATA/READ/RESTORE Support (Win64 Native)
#
# The table holds each item as written; see the System V tree.
#
# Data Table Format: 16-byte entries of
#   0  quoted flag (1 if the item was written in quotes)
#   8  pointer to the item's text, NUL-terminated
#
# Global State:
#   _data_table = Array of 16-byte entries (generated by compiler)
#   _data_count = Number of entries in table
#   _data_ptr   = Current read position (0-based index)
#
# Win64 Calling Convention:
#   - Args: rcx, rdx, r8, r9
#   - Callee-saved: rbx, rbp, rdi, rsi, r12-r15
#   - Shadow space: 32 bytes

# _rt_read_number - READ into a numeric variable
#
# The item's text must be a number and nothing else; see the System V twin.
#
# Arguments:
#   rcx = BASIC line number, for the diagnostic
#
# Returns:
#   xmm0 = value as double; 0 when there is nothing to read
.globl _rt_read_number
_rt_read_number:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    push r13
    push r14
    sub rsp, 32                         # shadow space; 16-byte aligned
    mov r12, rcx                        # line number
    mov rax, QWORD PTR [rip + _data_ptr]
    cmp rax, QWORD PTR [rip + _data_count]
    jae .Lread_num_none
    inc QWORD PTR [rip + _data_ptr]
    shl rax, 4
    lea rcx, [rip + _data_table]
    add rcx, rax                        # the entry
    cmp QWORD PTR [rcx], 0
    jne .Lread_num_syntax               # quoted: a string, not a number
    mov rbx, QWORD PTR [rcx + 8]        # its text
    mov rcx, rbx
    call lstrlenA
    mov r13, rax                        # its length
    test r13, r13
    jz .Lread_num_zero                  # an empty item is 0
    mov rcx, rbx
    mov rdx, r13
    call _rt_scan_number
    test edx, edx
    jnz .Lread_num_overflow
    test rax, rax
    jz .Lread_num_syntax
    # Only blanks may follow the number.
.Lread_num_rest:
    cmp rax, r13
    jae .Lread_num_done
    movzx ecx, BYTE PTR [rbx + rax]
    cmp ecx, 32
    je .Lread_num_blank
    cmp ecx, 9
    jne .Lread_num_syntax
.Lread_num_blank:
    inc rax
    jmp .Lread_num_rest

.Lread_num_none:
    lea rcx, [rip + _err_outofdata]
    jmp .Lread_num_raise
.Lread_num_syntax:
    lea rcx, [rip + _err_syntax]
    jmp .Lread_num_raise
.Lread_num_overflow:
    lea rcx, [rip + _err_overflow]
.Lread_num_raise:
    mov rdx, r12                        # line
    call _rt_error                      # returns only when trapped
.Lread_num_zero:
    xorpd xmm0, xmm0
.Lread_num_done:
    add rsp, 32
    pop r14
    pop r13
    pop r12
    pop rbx
    leave
    ret

# _rt_read_string - READ into a string variable: the item's text as written
#
# Arguments:
#   rcx = BASIC line number, for the diagnostic
#
# Returns:
#   rax = pointer to string data
#   rdx = string length; an empty string when there is nothing to read
.globl _rt_read_string
_rt_read_string:
    push rbp
    mov rbp, rsp
    push rbx
    sub rsp, 40                         # shadow space; 16-byte aligned
    mov rax, QWORD PTR [rip + _data_ptr]
    cmp rax, QWORD PTR [rip + _data_count]
    jae .Lread_str_none
    inc QWORD PTR [rip + _data_ptr]
    shl rax, 4
    lea rcx, [rip + _data_table]
    mov rbx, QWORD PTR [rcx + rax + 8]  # the text
    mov rcx, rbx
    call lstrlenA                         # DATA text is NUL-terminated
    mov rdx, rax
    mov rax, rbx
    add rsp, 40
    pop rbx
    leave
    ret
.Lread_str_none:
    mov rdx, rcx                        # line
    lea rcx, [rip + _err_outofdata]
    call _rt_error                      # returns only when trapped
    xor eax, eax
    xor edx, edx
    add rsp, 40
    pop rbx
    leave
    ret

# _rt_restore - Reset DATA pointer (RESTORE statement)
# Arguments:
#   rcx = new position (0-based index into data table)
# Returns: nothing
.globl _rt_restore
_rt_restore:
    mov QWORD PTR [rip + _data_ptr], rcx
    ret

# _rt_array_autodim - Create an array by using it, as GW-BASIC does
#
# See the System V twin.
#
# Arguments:
#   rcx = the descriptor, r8 = element size, r9 = the OPTION BASE,
#   rdx = the number of dimensions
# Returns: nothing (Out of memory leaves the pointer null)
.globl _rt_array_autodim
_rt_array_autodim:
    push rbp
    mov rbp, rsp
    push rbx
    push r12
    sub rsp, 32             # shadow space; 16-byte aligned
    mov rbx, rcx            # descriptor
    mov r12, r8             # running size: element size * the counts
    mov eax, 11
    sub rax, r9             # elements per dimension: base..10
    xor r10d, r10d          # dimension
.Lautodim_dim:
    cmp r10, rdx
    jae .Lautodim_alloc
    mov QWORD PTR [rbx + 8 + r10*8], rax
    lea r11, [rdx + r10]
    mov QWORD PTR [rbx + 8 + r11*8], r9
    imul r12, rax
    jo .Lautodim_nomem          # too large to address at all
    inc r10
    jmp .Lautodim_dim
.Lautodim_alloc:
    mov ecx, 1
    mov rdx, r12
    call calloc
    test rax, rax
    jz .Lautodim_nomem
    mov QWORD PTR [rbx], rax
    add rsp, 32
    pop r12
    pop rbx
    leave
    ret
.Lautodim_nomem:
    lea rcx, [rip + _err_memory]
    xor edx, edx
    call _rt_error          # returns only when trapped
    add rsp, 32
    pop r12
    pop rbx
    leave
    ret
